-- Venue Live Guest "Wedding Secret Garden". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara secretgarden), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'secretgarden', 'Wedding Secret Garden', 'secretgarden', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 146, 'center 38%',
  $t${"name":"Observatory","orn":"diamond","ui":{"ivory":"#FBF4EC","white":"#FFFFFF","soft":"#EBDDD0","soft2":"#C9A24A","accent":"#6E8548","deep":"#3F4A2A","ink":"#3F4A2A","mute":"#8B7D6A","line":"#E7D6C8","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F6ECDD","ink":"#3F4A2A","accent":"#6E8548","gold":"#C9A24A","leaf":"#EBDDD0","hbg":"rgba(251,244,236,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(63,74,42,.9)","acc":"#F2D27A","on":"#3F4A2A"},"scr":{"wine":"#3F4A2A","veil":"251,244,236"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'secretgarden');
